<section class="page-hero"><div><span class="eyebrow">A DIFFERENT WAY TO EXPLORE</span><h1><?= e($title) ?></h1><p><?= t('Thoughtful collections, assembled one discovery at a time.') ?></p></div><span class="page-hero-art"><?= icon('layers') ?></span></section><div class="collection-grid"><?php $rows=$a->db->all('SELECT * FROM cy_collections WHERE active=1 ORDER BY sort_order,id DESC LIMIT 100');foreach($rows as $collection): $count=$a->content->feed('all',$me,['collection'=>(int)$collection['id'],'size'=>1])['total']; ?><a class="collection-card panel glass reveal" href="<?= e(url('collection',['id'=>$collection['id']])) ?>"><span class="collection-symbol"><?= icon('book') ?></span><div><span class="eyebrow"><?= (int)$count ?> <?= t('Shared discoveries') ?></span><h2><?= e($collection['name']) ?></h2><p><?= e($collection['description']) ?></p></div><span class="text-link"><?= t('Explore the collection') ?><?= icon('arrow') ?></span></a><?php endforeach ?></div><?php if(!$rows){empty_state();} ?>
